import{c as o,S as t,j as a,m as r}from"./chunks/framework.C68YPdek.js";const g=JSON.parse('{"title":"Directories","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/directories.md","filePath":"developer/architecture/directories.md"}'),i={name:"developer/architecture/directories.md"};function d(n,e,s,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="directories" tabindex="-1">Directories <a class="header-anchor" href="#directories" aria-label="Permalink to “Directories”">​</a></h1><p>Three static JSON files tell the frontend what exists: the <strong>language directory</strong>, the <strong>plugin directory</strong> and the <strong>modules directory</strong>. All three are published on GitHub Pages and read by the browser at run time, so that adding a language, a tool or a module does not mean changing the frontend. Checked against the repositories and the published files on 28 November 2026.</p><h2 id="language-directory" tabindex="-1">Language directory <a class="header-anchor" href="#language-directory" aria-label="Permalink to “Language directory”">​</a></h2><p><a href="https://github.com/source-academy/language-directory" target="_blank" rel="noreferrer"><code>language-directory</code></a>; published at <a href="https://source-academy.github.io/language-directory/directory.json" target="_blank" rel="noreferrer">https://source-academy.github.io/language-directory/directory.json</a>.</p><ul><li>A <strong>language definition</strong> (<code>ILanguageDefinition</code>) has an id, a name, the evaluators that can run it, and optional settings: an editor configuration, a <code>textbook</code> (its label, route, base URL, cover image, and the <code>chapters</code> of the book that are written in this language, so that a snippet in a chapter runs in the right language), and <code>documentation</code> (the language&#39;s own documentation URL and its modules documentation URL, which make the frontend show a Documentation tab).</li><li>An <strong>evaluator definition</strong> (<code>IEvaluatorDefinition</code>) has an id, a name, the URL of the evaluator&#39;s entry file, its capabilities, and optionally a <code>plugin</code>: an id in the plugin directory whose tab presents what the evaluator computes. The host hides such an evaluator from the evaluator dropdown and selects it when the user opens that plugin&#39;s tab. This is how the Stepper, the E-Stepper and the CSE machine are offered: as evaluators of the same language that name a plugin.</li><li>Today it has 13 languages: Python §1, §2, §3, §4, §4 Typed and full Python; Source §1 to §4; Scheme; Java; OCaml. Python has several evaluators per language (compiled to JavaScript, a virtual machine, WebAssembly, CPython through Pyodide, and one for each tool). The evaluator URLs point to the GitHub Pages sites of the evaluator repositories (see <a href="./evaluators">Evaluators</a>).</li><li>To add a language, add its definition to <code>src/languages.ts</code>.</li></ul><h2 id="plugin-directory" tabindex="-1">Plugin directory <a class="header-anchor" href="#plugin-directory" aria-label="Permalink to “Plugin directory”">​</a></h2><p><a href="https://github.com/source-academy/plugin-directory" target="_blank" rel="noreferrer"><code>plugin-directory</code></a>.</p><ul><li>A <strong>plugin definition</strong> (<code>IPluginDefinition</code>) has an id, a name, an optional description, an optional <code>tab</code>, and <code>resolutions</code>. The <code>tab</code> gives the tab&#39;s id, label and icon, and whether the tab hides the host&#39;s REPL (<code>hidesRepl</code>) or keeps the side content from being resized (<code>resizable</code>), so that the host can show a placeholder and know how the tab behaves before the plugin loads. <code>resolutions</code> maps the kind of environment (web, runner, module) to the URL of the plugin&#39;s entry file; a plugin meant for the frontend&#39;s API has a web resolution, and one meant for Conductor&#39;s module API a module resolution.</li><li>Today it has four plugins: <code>stepper</code>, <code>e-stepper</code>, <code>data-visualizer</code> and <code>cse-machine</code>. To add one, add its definition to <code>src/plugins.ts</code>.</li><li><strong>Two copies are published.</strong> The repository&#39;s own Pages site serves <code>https://source-academy.github.io/plugin-directory/directory.json</code>, and the <code>plugins</code> repository&#39;s Pages site serves <code>https://source-academy.github.io/plugins/directory.json</code>; the frontend&#39;s default for <code>directory.plugin.url</code> is the second. Both list the same four ids today. Which of the two is the source of truth is not written down; until it is, a change to a plugin entry has to reach the one the frontend reads.</li></ul><h2 id="modules-directory" tabindex="-1">Modules directory <a class="header-anchor" href="#modules-directory" aria-label="Permalink to “Modules directory”">​</a></h2><p><a href="https://github.com/source-academy/modules" target="_blank" rel="noreferrer"><code>modules</code></a> publishes <code>https://source-academy.github.io/modules/modules.json</code>, the list of the default modules (<code>rune</code>, <code>plotly</code>, <code>curve</code>, <code>midi</code>, <code>repl</code>, <code>robot_simulation</code>, ...). A program&#39;s <code>import</code> is resolved against it; see <a href="./plugins-and-modules">Plugins and modules</a>.</p><h2 id="using-a-directory" tabindex="-1">Using a directory <a class="header-anchor" href="#using-a-directory" aria-label="Permalink to “Using a directory”">​</a></h2><p>The frontend bundles a copy of the language and plugin directories at a pinned tag (<code>@sourceacademy/language-directory</code> and <code>@sourceacademy/plugin-directory</code> in its <code>package.json</code>) and reads the published files at run time. Each directory can be imported as a package (bundled at build time, with the caution to pin a commit or tag), fetched as JSON at run time, or imported from its <code>index.js</code> as an external dependency. The repositories&#39; READMEs describe the three ways and how to test a change locally (<code>yarn start</code>, then set the feature flag to the local URL).</p>',12)])])}const p=o(i,[["render",d]]);export{g as __pageData,p as default};
